{% import "actions.awl" as actions %}

{% macro render(lib, emtype_id, emtype) %}

{{ lib.log('rendering EM type ' + emtype_id) }}

{#- create UDT for communication with the phase -#}



TYPE {{ lib.create_new_symbol(emtype_id + '_UDT', 'UDT', undefined, '') }} // {{emtype_id}}_UDT
VERSION : 0.1


STRUCT 
	{#- first part of the UDT containts the Setpoints from phase to EM -#}  
	{%- for io_name, io in lib.select_interface_io(emtype.Inputs) %}
	{{ io_name }}: {{ io.Type }};		// {{io.Comment}}{% if io.Comment_io != undefined %} - {{ io.Comment_io }}{% endif %}
	{%- endfor %}
	{%- for i in range (0, 40 - lib.count_s7_bytes(lib.select_interface_io(emtype.Inputs))) %}
	placeholder_SP_{{i}}: BYTE;  // placeholder
	{%- endfor %}
	{#- second part of the UDT containts the Process Values from EM to phase -#} 
	{%- for io_name, io in lib.select_interface_io(emtype.Outputs) %}
	{{ io_name }}: {{ io.Type }};		// {{io.Comment}}{% if io.Comment_io != undefined %} - {{ io.Comment_io }}{% endif %}
	{%- endfor %}
	{%- for i in range (0, 40 - lib.count_s7_bytes(lib.select_interface_io(emtype.Outputs))) %}
	placeholder_PV_{{i}}: BYTE;  // placeholder
	{%- endfor %}
END_STRUCT	
END_TYPE




{#- create label counters: reset also creates them if not existing -#}
{{ lib.reset_counter('statelabel') }}
{{ lib.reset_counter('condition_label') }}
{{ lib.reset_counter('error_label') }}
// ____{{emtype_id}}
FUNCTION_BLOCK "{{emtype_id}}"
TITLE = {{ emtype_id }}
// {{ emtype_id }}
{{ lib.comment_all_lines(emtype.Comment) }}
AUTHOR : 
FAMILY : 'emtyp'
NAME : namehead
VERSION : 0.1

VAR_INPUT

	sampletime { S7_sampletime := 'true' }: REAL ; // the scantime of this phase, used to increase timers
{#- add all the auto-generated inputs -#}
{% for input_name, input in emtype.Inputs %}
	{%- if input.template_io != true %}
	{{ input_name }}: {{ input.Type }};		// {{input.Comment}}{% if input.Comment_io != undefined %} - {{ input.Comment_io }}{% endif %}
	{%- endif %}
{%- endfor %}

END_VAR

VAR_OUTPUT

	// em_id: INT;	// unique number for every em instance over the whole project

	steptime_s: REAL;		// complete steptime in seconds. same value as the other steptimes
	steptime_m: REAL;		// complete steptime in minutes. same value as the other steptimes
	steptime_h: REAL;		// complete steptime in hours. same value as the other steptimes

	first_scan: BOOL;		// first scan of the step active
	last_scan: BOOL;		// last scan of the step active
	error_index_db: BOOL;	// em_id doesn't fit in the index db

	{# add all the auto-generated outputs -#}
{% for output_name, output in emtype.Outputs %}
	{%- if output.template_io != true %}
	{{ output_name }}: {{ output.Type }};		// {{output.Comment}}{% if output.Comment_io != undefined %} - {{ output.Comment_io }}{% endif %}
	{%- endif %}
{%- endfor %}

END_VAR



VAR

  previous_Command : INT;	// previous Command
  SP_PV: {{emtype_id}}_UDT;		// UDT for receiving Setpoints and sending Process Values

END_VAR


VAR_TEMP

	initial_scan: BOOL;			// pulse active on the first cycle of a new scan
	T_dbnum: INT;				// DB number of this block
	T_address: INT;				// address in the Index Table DB
	T_length: INT;				// length of the Index Table DB
{# add all the auto-generated temps -#}
{# start with the calculation values -#}
{% for i in range(1, emtype.var_counter.value) %}
	V{{i}}: REAL;					// intermediate value for calculation
{%- endfor %}
END_VAR

BEGIN

NETWORK
TITLE = Publish DB number to EM Index
//--------------------------------
// The EM will publish its DB number to the EM Index table
//--------------------------------

//### 0] init
	CLR;
	=	error_index_db;

//### 1] Check if the ID of this EM fits inside the EM Index table

    OPN   DB    25; //Open data block as shared data block
    L     DBLG; //Load length of shared data block (length of DB)
    T     #T_length; //transfer length to length

    L     #T_length; //length=length/2
    L     2; 
    /I    ; 
    T     #T_length; 

// Error and end the block if id bigger than length of the DB
    L     #T_length; 
    L     #em_id; 
    <=D   ; 
	= error_index_db;
    BEC   ; //if id is bigger than length end the block

//### 2] Write this DB number to the EM Index table

// find the number of the current fb
    L     DINO; 
    T     #T_dbnum; //find the db number of current fb

// calculate the real address	
    L     #em_id;
    L     2; 
    *I    ; 
    T     #T_address; 

// prepare the pointer for the location in the EM Index DB
// todo: can this code not simpeler? Probably no need to add with the zero-pointer	
    OPN   DB    25; 
    L     P#DBX 0.0; 
    L     #T_address; 
    SLD   3; 
    +D    ; 
    LAR1  ; 

//write the DB number to the real address
    L     #T_dbnum; 
    T     DBW [AR1,P#0.0]; 

NETWORK
TITLE = Copy all Setpoints from the UDT
//--------------------------------
// 
//--------------------------------

{% for io_name, io in lib.select_interface_io(emtype.Inputs) %}

	{% if io.Type == 'Bool' or  io.Type == 'BOOL' or io.Type == 'bool' %}
	A	SP_PV.{{io_name}};
	= 	{{io_name}}
	{% else %}
	L	SP_PV.{{io_name}};
	T	{{io_name}};
	{% endif %}

{%- endfor %}

NETWORK
TITLE = Acquiring logic
//--------------------------------
// 
//--------------------------------

	L	Request;
	T 	Owner;

NETWORK
TITLE = Steptimers
//--------------------------------
// If the previous Command is not the same as the current one
// then reset the timers, else increase them
// This is at the start of the FB because normal commandchanges will take
// till the next cycle to become active
//--------------------------------

// check if Command == previous_Command
	L 	Command;
	L	previous_Command;
	==I	;		// if condition true then {
	JCN TIM1;

	// increase timer
	L	sampletime;
	L	steptime_s;
	+R;
	T	steptime_s;

	JU TIM2	;	// } else {
TIM1: NOP 0	;	

	// reset timer
	L	0.0;
	T	steptime_s	;

TIM2: NOP 0;		// end if

// calculate the other two timers
	L 	steptime_s;
	L 	60.0;
	/R;
	T   steptime_m;

	L	60.0;
	/R;
	T	steptime_h;


NETWORK
TITLE = detect initial scan
//--------------------------------
// create a pulse active on the first cycle of a new scan
// this signal can be used in the state to execute some actions in the first cycle of the state
//
//--------------------------------

	L 	Command;
	L	previous_Command;
	<>I;
	=	initial_scan;


NETWORK
TITLE = Save old step
//--------------------------------
// Save old step
//--------------------------------

	L 	Command;
	T	previous_Command;


NETWORK
TITLE = Collect the errors from the CMs
//--------------------------------
// 
//--------------------------------

	CLR;
	{#- loop over all the inputs #}
	{%- for input_name, input_object in emtype.Inputs %}
		{%- if input_object.Error_Signal == true %}
	O	{{ input_name }};
		{%- endif %}
	{%- endfor %}
	=	CM_error;

NETWORK
TITLE = Assign a message number to each error
//--------------------------------
// This code tries to assign an error message to each CM error
// If multiple CMs have an error then it only stores one
// This is the EM type so we don't know which CM instance is connected
// So the error only contains the general name of the CM instance
// If the actual name needs to be shown then it could be deducted
// at a higher level using the CM name and EM instance 
//--------------------------------

	CLR;

	// clear the error no
	L	0;
	T CM_error_no;

	{# loop over all the inputs #}
	{%- for input_name, input_object in emtype.Inputs %}
		{%- if input_object.Error_Signal == true %}

	A	{{ input_name }};
	JCN	E{{ lib.increase_counter('error_label') }};

	L	{{ lib.get_message_id('CM error: ' + input_name ) }}; // 'CM error: {{ input_name }}'
	T 	CM_error_no;

E{{ lib.get_counter('error_label') }}:	NOP 0;	
		{%- endif %}
	{%- endfor %}



NETWORK
TITLE = START OF THE STATES
//################################
//################################
// Placeholder network to indicate the start of the actual sequence
//################################	  
//################################


	{#- loop over all the states #}
	{%- for state_number, state_object in emtype.States %}
NETWORK
TITLE = State {{state_number}}: {{ lib.firstline(state_object.Comment) | safe}}
//================================
{{ lib.comment_all_lines(state_object.Comment) | safe }} {# todo: create mini-FDS in each state comment as option #}
//================================	  

// skip this network if stepnumber not equal to {{state_number}}
	L 	Command;
	L 	{{state_number}};
	==I;
	JCN J{{ lib.increase_counter('statelabel') }};
{% if state_object.Actions_First_Scan != undefined %}	
//---------------------------------
// Actions (first scan)
//---------------------------------
	A	initial_scan; 
	JCN   C{{ lib.get_counter('statelabel') }};
		L -1.0;	 // value to show that the EM is in a state transition
		T Status;		
		{{- actions.render(lib, state_object.Actions_First_Scan) }}
	JU	D{{ lib.get_counter('statelabel') }};	//skip the continuous steps during the initial scan
C{{ lib.get_counter('statelabel') }}: NOP   0; 

{% endif %}
//---------------------------------
// Actions (continuous)
//---------------------------------
		{{- actions.render(lib, state_object.Actions) -}}

//---------------------------------
// --- CONDITIONS ---
//---------------------------------
			{#- first make calculations if the condition logic is too complex -#}
			{%- for calc in state_object.Conditions.condition_calc %}

// Calculation: {{calc.comment | safe}}
	L 	{{calc.v1.value}};
	L 	{{calc.v2.value}};
	{{calc.operation | safe}}R;
	{% if calc.boolean %}=	{{calc.value.value}};{% else %}T 	{{calc.value.value}};{% endif %}

			{%- endfor %}

// Condition Logic
	SET;	// make sure RLO is high so the state can happen when no conditions present
			{# then loop over the condition logic -#}
			{%- for logic in state_object.Conditions.transition_logic %}
	{{ lib.compact_logic(logic.logic, logic.invert) }}	{{logic.result.value}}; {% if logic.condition != undefined %}	// {{logic.condition | safe}}{% endif %}
			{%- endfor -%}
			{#- code for transferring to the next step #}
	JCN L{{ lib.get_counter('statelabel') }};

	L   Command;
	T   Status;

L{{ lib.get_counter('statelabel') }}: NOP 0;
{% if state_object.Actions_Last_Scan != undefined %}
//---------------------------------
// Actions (last scan)
// This is immediately executed once the command changes
//---------------------------------
	L	Command;
	L	previous_Command;
	<>I;
	JCN D{{ lib.get_counter('statelabel') }};
		{{- actions.render(lib, state_object.Actions_Last_Scan) }}	
{% endif %}
D{{ lib.get_counter('statelabel') }}: NOP 0;	

//---------------------------------
// End of network: jump here if step not active
// Jump to end of this FB if the step has been active to avoid
// execution of another step in the same scan
//---------------------------------		
	JU	ENDS;
J{{ lib.get_counter('statelabel') }}: NOP 0;

	{% endfor %}


NETWORK
TITLE = END OF THE STATES
//################################
//################################
// Placeholder network to indicate the end of the actual sequence
//################################	  
//################################

// jump location for the state that is currently active
ENDS:	NOP 0;

NETWORK
TITLE = General Actions - After
//--------------------------------
// General Actions - After
//--------------------------------

	{{- actions.render(lib, emtype.General_Actions.After) -}}


NETWORK
TITLE = Copy all Process Values to the UDT
//--------------------------------
// 
//--------------------------------

{% for io_name, io in lib.select_interface_io(emtype.Outputs) %}

	{% if io.Type == 'Bool' or  io.Type == 'BOOL' or io.Type == 'bool' %}
	A 	{{io_name}};
	=	SP_PV.{{io_name}};
	{% else %}
	L	{{io_name}};
	T	SP_PV.{{io_name}};
	{% endif %}

{%- endfor %}


NETWORK
TITLE = Clean up request
//--------------------------------
// Phases don't clean up their requests on the EM side
// So at the end of the EM reset the request
// If the phase is still there then it will write the request again by the next scan
//--------------------------------

	L 	0;
	T 	request;

END_FUNCTION_BLOCK
{% endmacro %}

FUNCTION "ROUND_R" : VOID
TITLE = ROUND REAL NUMBER TO N USER DEFINED DECIMAL PLACES

//################################################################################
//#              ROUND REAL NUMBER TO N USER DEFINED DECIMAL PLACES              #
//################################################################################
//
//Revisions history
//+--------------------------------------------------------------------------+
//! 2 !        !                               !              !              !
//+---+--------+-------------------------------+--------------+--------------!
//! 1 !19/09/21!ISSUE                          ! Leonardo     !              !
//+---+--------+-------------------------------+--------------+--------------!
//!Rev!Date    !Description                    !Drawn         !Checked       !
//+--------------------------------------------------------------------------+
//
//Function         : This block rounds a real value to a N user defined decimal 
//                  place. The result is rounded to the closest value.
//                  Eg.: 1.68345623 round to 3 decimal place = 1.683
//                  Useful when values changes rapidly and you want to keep only
//                  the last n relevant/invariant decimal places.
//
//Calling block    : ANY
//
//Used DB          : 
//                     
//Used Flags       : 
// 
//Used prog.block  : 
//
//Remarks          :


AUTHOR : LEONARDO
FAMILY : MATH
NAME : ROUND_R
VERSION : 1.0


VAR_INPUT
  R_IN : REAL ;	    //Value to round
  I_IN : INT ;	    //Decimal places to round
END_VAR
VAR_OUTPUT
  R_OUT : REAL ;	//Rounded value
END_VAR
VAR_TEMP
  R_DECIMAL_PLACE : REAL ;	
  R_TEMP : REAL ;	
END_VAR
BEGIN
NETWORK
TITLE =Future...
//Choose the way to round the value:
//  CEIL
//  FLOOR
//  ROUND
//  TRUNC


NETWORK
TITLE =Convet decimal places from int to real

      CALL "I_R" (
           I_IN                     := #I_IN,
           R_OUT                    := #R_DECIMAL_PLACE);
      NOP   0; 
NETWORK
TITLE =Calculate decimal places
//Uses POW function from MATH library.
//
      CALL "POW" (
           x                        := 1.000000e+001,
           b                        := #R_DECIMAL_PLACE,
           y                        := #R_DECIMAL_PLACE);
      NOP   0; 
NETWORK
TITLE =Real rounded to n decimal places

      L     #R_IN; 
      L     #R_DECIMAL_PLACE; 
      *R    ; // Multiply value to round * decimal places
      RND   ; // Round to exclude values below defined decimal places
      DTR   ; // Convert  Double Integer to Real
      L     #R_DECIMAL_PLACE; 
      /R    ; // Devide by defined decimal places
      T     #R_OUT; 
      SET   ; 
      SAVE  ; 
      CLR   ; 
END_FUNCTION

FUNCTION_BLOCK "MOTOR v4.3"
TITLE =Motor with CD and SS sensors
//Motor control function.
AUTHOR : splanken
FAMILY : EQUIP
NAME : MOTOR
VERSION : 4.3


VAR_INPUT
  Sensor_options : BYTE ;	//Bits:0=CD;1=SS;2=SS-4B; 3=TD
  Start_rqd_man : BOOL ;	//Manual mode start request
  Start_rqd_auto : BOOL ;	//Auto mode start request
  Manual_mode : BOOL ;	//Manual mode (1=manual; 0=auto)
  Estop_alarm : BOOL ;	//Emergency stop alarm active
  Alarm_reset : BOOL ;	//Reset any alarms for this equipment
  EQ_CD : BOOL ;	//Motor choke detector device
  EQ_SS : BOOL ;	//Motor speed switch device
  EQ_TD : BOOL ;	//Equipment takeup detection switch
  EQ_MS : BOOL ;	//Contactor running status
  M_off_time : TIME ;	//Delay between starts (0=none)
  M_max_time : TIME ;	//Contactor maximum response time (0=indefinite)
  CD_max_time : TIME ;	//Choke detector maximum off time (must be >0 if option enabled)
  TD_max_time : TIME ;	//Takeup detection maximum off time (must be >0 if option enabled)
  SS_start_delay : TIME ;	//Speed switch startup delay (must be >0 if option enabled)
  SS_max_on_time : TIME ;	//Speed switch maximum ON time (must be >0 if option enabled)
  SS_max_off_time : TIME ;	//Speed switch maximum off time (must be >0 if option enabled)
END_VAR
VAR_IN_OUT
  OK_to_start : BOOL ;	
  EQ_M : BOOL ;	//Contactor coil signal for run
  Running : BOOL ;	//Indication for HMI motor running
  Alarm_M : BOOL ;	//Motor start alarm
  Alarm_CD : BOOL ;	//Choke detector alarm
  Alarm_TD : BOOL ;	//Takeup detection alarm
  Alarm_SS : BOOL ;	//Speed switch alarm
  Alarm_general : BOOL ;	//General alarm (any active alarm)
END_VAR
VAR
  Off_delay : "TON";	
  T_SS_start : "TON";	//IEC timer for speed switch start delay
  T_SS_on : "TON";	//IEC timer for speed switch on time
  T_SS_off : "TON";	//IEC timer for speed switch off time
  T_CD : "TON";	//IEC timer for choke detector
  T_TD : "TON";	
  T_M : "TON";	//IEC timer for contactor feedback
  Alarm : STRUCT 	//Alarm structure
   SS_on : BOOL ;	
   SS_off : BOOL ;	
   CD : BOOL ;	
   TD : BOOL ;	
   M : BOOL ;	
  END_STRUCT ;	
  SS : STRUCT 	
   Start_dly_done : BOOL ;	//Motor start delay expired for speed switch
   On_pls : BOOL ;	//Speed switch on pulse
   Off_pls : BOOL ;	//Speed switch off pulse
   On_time : TIME ;	//Speed switch current on time
   Off_time : TIME ;	//Speed switch current off time
   Last_on_time : TIME ;	//Speed switch last measaured on time
   Last_off_time : TIME ;	//Speed switch last measured off time
  END_STRUCT ;	
  Option : STRUCT 	
   CD : BOOL ;	
   TD : BOOL ;	
   SS : BOOL ;	
   SS4B : BOOL ;	
  END_STRUCT ;	
  Running_last : BOOL ;	
END_VAR
VAR_TEMP
  Off_dly_OK : BOOL ;	
END_VAR
BEGIN
NETWORK
TITLE =Check which options to use
//v4.3:  11Oct16: Added takeup detection input.
//       Options: bit 0 = CD sensor
//                bit 1 = SS sensor (pulse)
//                bit 2 = SS sensor (4B Whirligig)
//                bit 3 = TD sensor
//       Note: Bit 1 & 2 cannot be combined
//    :  Allow off delay of 0.
//v4.2:  Intermediate (ignore off delay if time = T#0s)
//v4.12: 11Oct16: Added additional motor trip detection.
//v4.11: 17Sep15: Also consider E-stop alarm in ok to start evaluation.
//v4.1 : 09Mar15: Add off time delay for motor starts and OK to start.
//v4.0 : 02Mar15: Combined all CD/SS/SS4B options into one generic FB.
//       Options: bit 0 = CD sensor
//                bit 1 = SS sensor (pusle)
//                bit 2 = SS sensor (4B Whirligig)
//       Note: Bit 1 & 2 cannot be combined
//v3.0 : 23Feb15: Rewrite using IEC timers for cleaner code.
// Check bit 0 for CD sensor
      L     #Sensor_options; 
      AW    W#16#1; 
      L     W#16#1; 
      ==I   ; 
      =     #Option.CD; // Monitor choke detector

// Check bit 1 for SS sensor
      L     #Sensor_options; 
      AW    W#16#2; 
      L     W#16#2; 
      ==I   ; 
      =     #Option.SS; // Monitor pulsating speed switch

// Check bit 2 for SS 4B (stop motion) sensor
// This option cannot be used with a regular SS sensor
      L     #Sensor_options; 
      AW    W#16#4; 
      L     W#16#4; 
      ==I   ; 
      AN    #Option.SS; 
      =     #Option.SS4B; // Monitor 4B type speed switch

// Check bit 3 for TD sensor
      L     #Sensor_options; 
      AW    W#16#8; 
      L     W#16#8; 
      ==I   ; 
      =     #Option.TD; 
NETWORK
TITLE =Indicate running
//Indicate running if we energized the contactor and received the status feedback 
//from the contactor.
      A     #EQ_M; 
      A     #EQ_MS; 
      =     #Running; 
NETWORK
TITLE =Off delay

      AN    #Running; 
      =     L      1.0; 
      BLD   103; 
      CALL #Off_delay (
           IN                       := L      1.0,
           PT                       := #M_off_time);

      NOP   0; 
NETWORK
TITLE =Off delay OK

      O     #Off_delay.Q; 
      O(    ; 
      L     #Off_delay.PT; 
      L     L#0; 
      <=D   ; 
      )     ; 
      =     #Off_dly_OK; 
NETWORK
TITLE =Start delay
//Before monitoring the speed switch input timing we allow the motor to ramp up.
      A     #Running; 
      =     L      1.0; 
      BLD   103; 
      CALL #T_SS_start (
           IN                       := L      1.0,
           PT                       := #SS_start_delay,
           Q                        := #SS.Start_dly_done);

      NOP   0; 
NETWORK
TITLE =Record the last on/off times
//This is not critical to operation but it helps in setting up proper timing for 
//this equipment.
      A     #EQ_SS; 
      =     L      1.0; 
      A     L      1.0; 
      FP    #SS.On_pls; 
      JNB   _001; 
      L     #SS.Off_time; 
      T     #SS.Last_off_time; 
_001: NOP   0; 
      A     L      1.0; 
      FN    #SS.Off_pls; 
      JNB   _002; 
      L     #SS.On_time; 
      T     #SS.Last_on_time; 
_002: NOP   0; 
NETWORK
TITLE =Speed switch time ON
//Once ramped up, verify the ON time is within the limit (motor can stop with 
//input active.)
      A     #SS.Start_dly_done; 
      A     #EQ_SS; 
      =     L      1.0; 
      BLD   103; 
      CALL #T_SS_on (
           IN                       := L      1.0,
           PT                       := #SS_max_on_time,
           Q                        := #Alarm.SS_on,
           ET                       := #SS.On_time);
      NOP   0; 
NETWORK
TITLE =Speed switch time off
//Once ramped up, verify the OFF time is within the limit.
      A     #SS.Start_dly_done; 
      AN    #EQ_SS; 
      =     L      1.0; 
      BLD   103; 
      CALL #T_SS_off (
           IN                       := L      1.0,
           PT                       := #SS_max_off_time,
           Q                        := #Alarm.SS_off,
           ET                       := #SS.Off_time);
      NOP   0; 
NETWORK
TITLE =Speed switch alarm
//Construction in separate network since TIA Portal does ot have EN/ENO for IEC 
//timers.
      A     #Option.SS; 
      A(    ; 
      O     #Alarm.SS_on; 
      O     #Alarm.SS_off; 

      )     ; 
      S     #Alarm_SS; 
NETWORK
TITLE =Speed switch alarm (4B)
//Construction in separate network since TIA Portal does ot have EN/ENO for IEC 
//timers.
      A     #Option.SS4B; 
      A     #SS.Start_dly_done; 
      AN    #EQ_SS; 
      S     #Alarm_SS; 
NETWORK
TITLE =Choke detector time
//Verify the choke detector input is active while running. If not running, this 
//will not trigger a fault.
//It could be safer to declare an alarm even when #Running is false. Otherwise, 
//the motor is allowed to start for the short duration that the choke input is 
//allowed to be absent. This could be a problem on larger motors under heavy 
//load.
      A     #Running; 
      AN    #EQ_CD; 
      =     L      1.0; 
      BLD   103; 
      CALL #T_CD (
           IN                       := L      1.0,
           PT                       := #CD_max_time,
           Q                        := #Alarm.CD);

      NOP   0; 
NETWORK
TITLE =CD alarm
//Construction in separate network since TIA Portal does ot have EN/ENO for IEC 
//timers.
      A     #Option.CD; 
      A     #Alarm.CD; 
      S     #Alarm_CD; 
NETWORK
TITLE =TD time

      A     #Running; 
      AN    #EQ_TD; 
      =     L      1.0; 
      BLD   103; 
      CALL #T_TD (
           IN                       := L      1.0,
           PT                       := #TD_max_time,
           Q                        := #Alarm.TD);

      NOP   0; 
NETWORK
TITLE =TD alarm

      A     #Option.TD; 
      A     #Alarm.TD; 
      S     #Alarm.TD; 
NETWORK
TITLE =Motor start time
//Once energizing the PLC output to the coil, we expect a status feedback within 
//a short amount of time. If not we create a motor start fault.
      A     #EQ_M; 
      AN    #EQ_MS; 
      =     L      1.0; 
      BLD   103; 
      CALL #T_M (
           IN                       := L      1.0,
           PT                       := #M_max_time,
           Q                        := #Alarm.M);

      NOP   0; 
NETWORK
TITLE =Motor start alarm (secondary)
//Created a new version 2.12. In a project if the contactor de-energized due to a 
//MSP trip the manual start would clear (correctly) but it would not write a 
//motor start fault. As a work-around, we store the running status at the end of 
//the block. If the running status was on, we are still sending power to the 
//coil, but we are failing to detect the coil status, we write a motor start 
//fault.
      A     #Running_last; 
      A     #EQ_M; 
      AN    #EQ_MS; 
      S     #Alarm_M; 
NETWORK
TITLE =Motor start alarm
//Construction in separate network since TIA Portal does ot have EN/ENO for IEC 
//timers.
      A     #Alarm.M; 
      S     #Alarm_M; 
NETWORK
TITLE =General alarm
//Combine all alarms. This can be used for an HMI where only one boolean can be 
//used for visualization/visibility.
      O     #Alarm_SS; 
      O     #Alarm_CD; 
      O     #Alarm.TD; 
      O     #Alarm_M; 
      S     #Alarm_general; 
NETWORK
TITLE =OK to start
//If there is no emergency stop alarm, no motor related alarm, and the off delay 
//has expired, the motor can start. In manual mode, the manual start should be 
//cleared outside this FB when it is not OK to start.
      A(    ; 
      O     #Off_dly_OK; 
      O     #Running; 
      )     ; 
      AN    #Alarm_general; 
      AN    #Estop_alarm; 
      =     #OK_to_start; 
NETWORK
TITLE =Energize contactor coil
//If there is no emergency stop alarm, no general alarm from this equipment, and 
//a valid run command was received, energize the contactor coil.
      A     #OK_to_start; 
      A(    ; 
      A     #Manual_mode; 
      A     #Start_rqd_man; 
      O     ; 
      AN    #Manual_mode; 
      A     #Start_rqd_auto; 
      )     ; 
      =     #EQ_M; 
NETWORK
TITLE =Clear alarms
//On a reset request, clear all alarms.
      A     #Alarm_reset; 
      R     #Alarm_general; 
      R     #Alarm_SS; 
      R     #Alarm_CD; 
      R     #Alarm.TD; 
      R     #Alarm_M; 
NETWORK
TITLE =Store the current running state
//v4.12: Used in additional motor start fault detection.
      A     #Running; 
      =     #Running_last; 
NETWORK
TITLE =Return ENO

      A     #Running; 
      SAVE  ; 
END_FUNCTION_BLOCK

