﻿FUNCTION_BLOCK "#DBMS"
TITLE = DBMS
{ S7_Optimized_Access := 'FALSE' }
AUTHOR : QLR
FAMILY : dnomaiD
VERSION : 10.0
//TABLE: BarcodeData.Code | BarcodeData.Scanner | DateTime
//PRIMARY KEY: BarcodeData.Code
   VAR_INPUT 
      PerEmptyAuto : Bool;   // Allow to empty db when it is full
