         TON_StatusPermInsert_nDB : Bool;
      END_STRUCT;
      COUNT : Struct
         cA00 : Int;
         cB00 : Int;
         cD00 : Int;
         cF00 : Int;
         dA00 : Int;
         dC00 : Int;
         dE00 : Int;
         fA00 : Int;
         fA01 : Int;
         fA02 : Int;
         gA00 : Int;
         hA00 : Int;
         hA01 : Int;
         hA02 : Int;
      END_STRUCT;
      SAVE_AR1 : Struct
         dC00 : DWord;
         dE00 : DWord;
         fA10 : DWord;
