      MaxQuantityDB : Int;   // Maxim quantity DB
      NetworkReturn : Int;   // Network return
      DataInputOK : Bool;   // Data input OK
      DigitFilter : "UDT_BARCODE";   // ::EAN-13
   END_VAR

   VAR_TEMP 
      Code : "UDT_BARCODE_CODE";
      SaveAR1 : DWord;
      SaveSTW : DWord;
      ANY_DB_SELECT_I : Any;
      ANY_DB_SELECT_F : Any;
      ANY_DB1_I : Any;
      ANY_DB1_F : Any;
      ANY_DB1_B : Any;
      ANY_DB1_IE : Any;
      ANY_DB1_FE : Any;
      ANY_DB2_I : Any;
      ANY_DB2_F : Any;
      ANY_DB2_IE : Any;
      ANY_DB2_FE : Any;
      ANY_DB3_I : Any;
      ANY_DB3_F : Any;
      ANY_DB3_IE : Any;
      ANY_DB3_FE : Any;
      ANY_DB4_I : Any;
      ANY_DB4_F : Any;
      ANY_DB4_IE : Any;
      ANY_DB4_FE : Any;
      ANY_DB5_I : Any;
      ANY_DB5_F : Any;
      ANY_DB5_IE : Any;
      ANY_DB5_FE : Any;
      ANY_DB6_I : Any;
      ANY_DB6_F : Any;
      ANY_DB6_IE : Any;
      ANY_DB6_FE : Any;
      ANY_DB_QUERY : Any;
      ANY_DB_DELETE : Any;
      PAUXnDB : Int;
      PanDB : Array[1..6] of Int;
      P_STATUS : Struct
         nDB : Int;
         Adr_S_DB : DWord;
         Adr_E_DB : DWord;
         PermInsert : Bool;
         PermOut : Bool;
         MemFull : Bool;
         PermPush : Bool;
      END_STRUCT;
      P_ADR : Struct
         AUX : DWord;
         I : DWord;
         F : DWord;
         I_DB : Array[1..6] of DWord;
