         COMP_01 : DWord;
         COMP_02 : DWord;
      END_STRUCT;
      LIST_DB_T : "UDT_DATABASE_DB_LIST";
   END_VAR

   VAR CONSTANT 
      Network_1 : Int := 100;
      Network_2 : Int := 200;
      Network_3 : Int := 300;
      Network_4 : Int := 400;
      Network_5 : Int := 500;
      Network_6 : Int := 600;
      Network_7 : Int := 700;
      Network_8 : Int := 800;
      Network_9 : Int := 900;
      Network_10 : Int := 1000;
      Network_11 : Int := 1100;
      Network_12 : Int := 1200;
      Network_13 : Int := 1300;
      Network_14 : Int := 1400;
      Network_15 : Int := 1500;
      Network_16 : Int := 1600;
      Network_17 : Int := 1700;
      LogInsert : Int := 1;   // Insert
      LogDelete : Int := 2;   // Delete
      LogDataAvailable : Int := 3;   // Query: Data available
      LogDataNotAvailable : Int := 4;   // Query: Data not available
      LogDataInputNOK : Int := 5;   // Data input NOK
      LogFullData : Int := 6;   // No inserted data base full
   END_VAR


BEGIN
NETWORK
TITLE = --Start--
      L #Network_1;
      T #P_RET_VAL.MEM;
      TAR1 #SaveAR1;
      L STW;
      T #SaveSTW;

      A #Reset;
      JC AA;
      A #FAULT;
      S #Status.Fb_Fault;
      JC END;
      A #DATA_ERROR;
      S #Status.DataError;
      JC AF;
AA:      NOP 0;
      R #FAULT;
      R #Status.Fb_Fault;
      R #DATA_ERROR;
      R #Status.DataError;
AF:      NOP 0;
NETWORK
TITLE = --Timer--
      CALL TOF, #TIME_FillAll
      {time_type := 'Time'}
      (  IN                          := #FULL , 
         PT                          := t#250ms
      );

      A #TIME_FillAll.Q;
      = #Status.Mem.FillAll;

      CALL TON, #TIME_StatusPermInsert_nDB
      {time_type := 'Time'}
      (  IN                          := #AUX.StatusPermInsert_nDB , 
         PT                          := t#250ms
      );

      A #TIME_StatusPermInsert_nDB.Q;
      = #AUX.TON_StatusPermInsert_nDB;

NETWORK
TITLE = --Setting--
      L #Network_3;
      T #P_RET_VAL.MEM;
      L P##Code;
      L P##SaveAR1;
      XOD;
      L 8;
      /D;
      T #LENGTH.Code;
      L ' ';
      T #AUX.xByte;
      CALL FILL
      {ptr_type := 'Variant'}
      (  BVAL                        := #AUX.xByte , 
         RET_VAL                     := #P_RET_VAL.X , 
         BLK                         := #IniData.BarcodeData.Code
      );
      L 0;
      T #AUX.xInt;
      L P##FAULT;
      L P##IniData;
      -D;
      T #LENGTH.PointerData;
      L 8;
      /D;
      T #LENGTH.Data;
      CLR;
      = #AUX.FullDatabase;
      L 5;
      T #MaxQuantityDB;
      L #LIST_DB.DbNumber[1];
      T #LIST_DB_T.DbNumber[1];
      L #LIST_DB.DbNumber[2];
      T #LIST_DB_T.DbNumber[2];
      L #LIST_DB.DbNumber[3];
      T #LIST_DB_T.DbNumber[3];
      L #LIST_DB.DbNumber[4];
      T #LIST_DB_T.DbNumber[4];
      L #LIST_DB.DbNumber[5];
      T #LIST_DB_T.DbNumber[5];
      L 0;
      T #LIST_DB_T.DbNumber[6];
      L 0;
      T #AuxQuantityDB;

      L P##LIST_DB;
      LAR1;
      L W[ AR1, P#0.0];
      T #NDB;
      L W[ AR1, P#4.0];
      LAR1;
bA01:      NOP 0;
      OPN DB[ #NDB];
      L DBW[ AR1, P#0.0];
      L 0;
      ==I;
      JC bA02;
      L #AuxQuantityDB;
      L 1;
      +I;
      T #AuxQuantityDB;
      L #MaxQuantityDB;
      L #AuxQuantityDB;
      <=I;
      JC bA02;
      L P#2.0;
      +AR1;
      JU bA01;
bA02:      NOP 0;
      L #AuxQuantityDB;
      L 1;
      <I;
      S #FAULT;
      JC END;
      L #AuxQuantityDB;
      L #MaxQuantityDB;
      >I;
      S #FAULT;
      JC END;
      L #AuxQuantityDB;
      T #QuantityDB;
      L #QuantityDB;
      T #LIST_DB.QuantityDB;
      T #LIST_DB_T.QuantityDB;
NETWORK
TITLE = cA..Any DB
      L #Network_4;
      T #P_RET_VAL.MEM;
      L #MaxQuantityDB;
      T #QuantityLabelDB;
      L 1;
      T #COUNT.cA00;
      JU cA00;
cA00:      NOP 0;
      L #COUNT.cA00;
      JL cAXX;
      JU cAFF;
      JU cA11;//Any db[1]: First> data
      JU cA12;//Any db[1]: First> data, Length> all data - 1  
      JU cA13;//Any db[1]: Last> data 
      JU cA14;//Any db[1]: Second> data, Length> all data - 1
      JU cA21;//Any db[2]: First> data
      JU cA22;//Any db[2]: First> data, Length> all data - 1
      JU cA23;//Any db[2]: Last> data
      JU cA24;//Any db[2]: Second> data, Length> all data - 1
      JU cA31;//Any db[3]: First> data
      JU cA32;//Any db[3]: First> data, Length> all data - 1
      JU cA33;//Any db[3]: Last> data
      JU cA34;//Any db[3]: Second> data, Length> all data - 1
      JU cA41;//Any db[4]: First> data
      JU cA42;//Any db[4]: First> data, Length> all data - 1
      JU cA43;//Any db[4]: Last> data
      JU cA44;//Any db[4]: Second> data, Length> all data - 1
      JU cA51;//Any db[5]: First> data
      JU cA52;//Any db[5]: First> data, Length> all data - 1
      JU cA53;//Any db[5]: Last> data
      JU cA54;//Any db[5]: Second> data, Length> all data - 1
      JU cA61;//Any db[6]: First> data
      JU cA62;//Any db[6]: First> data, Length> all data - 1
      JU cA63;//Any db[6]: Last> data
      JU cA64;//Any db[6]: Second> data, Length> all data - 1
cAXX:      JU cAFF;
cA11:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[1]];
      L DBNO;
      T #PanDB[1];
      T #PAUXnDB;//Aux
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      L P#0.0;
      L DW#16#84000000;
      +D;
      T #P_ADR.I_DB[1];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB1_I;
      JU cAFI;
cA12:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[1]];
      L DBLG;
      L #LENGTH.Data;
      /D;
      T #NumDataArrayDB[1];
      L -1;
      +I;
      L #LENGTH.Data;
      *I;
      T #LENGTH.AllDataPushDB[1];
      T #AUX.LNG;//Aux
      L #P_ADR.I_DB[1];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB1_IE;
      JU cAFI;
cA13:      NOP 0;
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      OPN DB[ #LIST_DB_T.DbNumber[1]];
      L DBLG;
      L #LENGTH.Data;
      -D;
      L 8;
      *D;
      L DW#16#84000000;
      +D;
      T #P_ADR.F_DB[1];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB1_F;
      JU cAFI;
cA14:      NOP 0;
      L #LENGTH.AllDataPushDB[1];
      T #AUX.LNG;//Aux
      L #LENGTH.PointerData;
      L DW#16#84000000;
      +D;
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB1_FE;
      JU cAFI;
cA21:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[2]];
      L DBNO;
      T #PanDB[2];
      T #PAUXnDB;//Aux
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      L P#0.0;
      L DW#16#84000000;
      +D;
      T #P_ADR.I_DB[2];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB2_I;
      JU cAFI;
cA22:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[2]];
      L DBLG;
      L #LENGTH.Data;
      /D;
      T #NumDataArrayDB[2];
      L -1;
      +I;
      L #LENGTH.Data;
      *I;
      T #LENGTH.AllDataPushDB[2];
      T #AUX.LNG;//Aux
      L #P_ADR.I_DB[2];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB2_IE;
      JU cAFI;
cA23:      NOP 0;
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      OPN DB[ #LIST_DB_T.DbNumber[2]];
      L DBLG;
      L #LENGTH.Data;
      -D;
      L 8;
      *D;
      L DW#16#84000000;
      +D;
      T #P_ADR.F_DB[2];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB2_F;
      JU cAFI;
cA24:      NOP 0;
      L #LENGTH.AllDataPushDB[2];
      T #AUX.LNG;//Aux
      L #LENGTH.PointerData;
      L DW#16#84000000;
      +D;
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB2_FE;
      JU cAFI;
cA31:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[3]];
      L DBNO;
      T #PanDB[3];
      T #PAUXnDB;//Aux
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      L P#0.0;
      L DW#16#84000000;
      +D;
      T #P_ADR.I_DB[3];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB3_I;
      JU cAFI;
cA32:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[3]];
      L DBLG;
      L #LENGTH.Data;
      /D;
      T #NumDataArrayDB[3];
      L -1;
      +I;
      L #LENGTH.Data;
      *I;
      T #LENGTH.AllDataPushDB[3];
      T #AUX.LNG;//Aux
      L #P_ADR.I_DB[3];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB3_IE;
      JU cAFI;
cA33:      NOP 0;
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      OPN DB[ #LIST_DB_T.DbNumber[3]];
      L DBLG;
      L #LENGTH.Data;
      -D;
      L 8;
      *D;
      L DW#16#84000000;
      +D;
      T #P_ADR.F_DB[3];
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB3_F;
      JU cAFI;
cA34:      NOP 0;
      L #LENGTH.AllDataPushDB[3];
      T #AUX.LNG;//Aux
      L #LENGTH.PointerData;
      L DW#16#84000000;
      +D;
      T #P_ADR.AUX;//Aux
      LAR1 P##ANY_DB3_FE;
      JU cAFI;
cA41:      NOP 0;
      OPN DB[ #LIST_DB_T.DbNumber[4]];
      L DBNO;
      T #PanDB[4];
      T #PAUXnDB;//Aux
      L #LENGTH.Data;
      T #AUX.LNG;//Aux
      L P#0.0;
      L DW#16#84000000;
