	T 	PIC01_SP;

// Action: PIC01_SET_SP = true
	SET;
	=	PIC01_SET_SP;

	JU	D5;	//skip the continuous steps during the initial scan
C5: NOP   0; 


//---------------------------------
// Actions (continuous)
//---------------------------------

// Action: start Pump
	SET;
	=	Pump_ON;

// Action: auto Pressure_SP PIC01
	SET;
	=	PIC01_AUT;

// Action: open BV_Bottom
	SET;
	=	BV_Bottom_CMD;

// Action: open BV_Tran_M04
	SET;
	=	BV_Tran_M04_CMD;

// Action: PIC01_SET_SP = false
	CLR;
	=	PIC01_SET_SP;
//---------------------------------
// --- CONDITIONS ---
