// Condition Logic
	SET;	// make sure RLO is high so the state can happen when no conditions present

	A	Pump_RUN; 	// Pump start
	A	BV_Bottom_OPN; 	// BV_Bottom open
	A	BV_Tran_M04_OPN; 	// BV_Tran_M04 open
	JCN L5;

